public class WildcardImportResolverTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        WildcardImportResolver resolver = new WildcardImportResolver("com.app");
        resolver.declarePackage("java.lang", "String", "Integer");
        resolver.declarePackage("java.util", "List", "Map");
        resolver.declarePackage("java.awt", "List", "Color");
        resolver.declarePackage("com.app", "Widget", "Color");

        check("java.lang is always imported", "java.lang.String", resolver.resolve("String"));
        check("unknown name", null, resolver.resolve("Nothing"));
        check("not imported yet", null, resolver.resolve("Map"));

        resolver.importPackage("java.util");
        check("wildcard import found", "java.util.Map", resolver.resolve("Map"));

        resolver.importPackage("java.awt");
        check("two wildcards clash", "AMBIGUOUS", resolver.resolve("List"));

        resolver.importType("java.util.List");
        check("single type import wins", "java.util.List", resolver.resolve("List"));

        check("own package beats a wildcard", "com.app.Color", resolver.resolve("Color"));
        check("own package class", "com.app.Widget", resolver.resolve("Widget"));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

