public class WildcardImportResolver {

    private final String currentPackage;
    private final java.util.Map<String, java.util.Set<String>> declared = new java.util.TreeMap<>();
    private final java.util.Map<String, String> singleTypeImports = new java.util.TreeMap<>();
    private final java.util.Set<String> wildcardImports = new java.util.TreeSet<>();

    public WildcardImportResolver(String currentPackage) {
        this.currentPackage = currentPackage == null ? "" : currentPackage;
    }

    public void declarePackage(String packageName, String... classNames) {
        java.util.Set<String> members = declared.get(packageName);
        if (members == null) {
            members = new java.util.TreeSet<>();
            declared.put(packageName, members);
        }
        for (String className : classNames) {
            members.add(className);
        }
    }

    public void importType(String fullyQualifiedName) {
        int lastDot = fullyQualifiedName.lastIndexOf('.');
        if (lastDot < 0) {
            return;
        }
        singleTypeImports.put(fullyQualifiedName.substring(lastDot + 1), fullyQualifiedName);
    }

    public void importPackage(String packageName) {
        wildcardImports.add(packageName);
    }

    public String resolve(String simpleName) {
        if (simpleName == null) {
            return null;
        }
        if (singleTypeImports.containsKey(simpleName)) {
            return singleTypeImports.get(simpleName);
        }
        if (declares(currentPackage, simpleName)) {
            return qualify(currentPackage, simpleName);
        }
        java.util.Set<String> searched = new java.util.TreeSet<>(wildcardImports);
        searched.add("java.lang");
        java.util.Set<String> hits = new java.util.TreeSet<>();
        for (String packageName : searched) {
            if (declares(packageName, simpleName)) {
                hits.add(qualify(packageName, simpleName));
            }
        }
        if (hits.isEmpty()) {
            return null;
        }
        if (hits.size() > 1) {
            return "AMBIGUOUS";
        }
        return hits.iterator().next();
    }

    private boolean declares(String packageName, String simpleName) {
        java.util.Set<String> members = declared.get(packageName);
        return members != null && members.contains(simpleName);
    }

    private static String qualify(String packageName, String simpleName) {
        return packageName.isEmpty() ? simpleName : packageName + "." + simpleName;
    }
}
